importScripts('../vendor/lame.min.js');
self.onmessage=e=>{try{let left=new Float32Array(e.data.left),right=new Float32Array(e.data.right),encoder=new lamejs.Mp3Encoder(2,e.data.sampleRate,[128,192,256,320].includes(e.data.bitrate)?e.data.bitrate:128),parts=[],last=0;function pcm(a,start,n){let b=new Int16Array(n);for(let i=0;i<n;i++){let s=Math.max(-1,Math.min(1,a[start+i]||0));b[i]=s<0?s*32768:s*32767;}return b;}for(let i=0;i<left.length;i+=1152){let n=Math.min(1152,left.length-i),chunk=encoder.encodeBuffer(pcm(left,i,n),pcm(right,i,n));if(chunk.length)parts.push(new Uint8Array(chunk));if(i-last>44100){self.postMessage({progress:i/left.length});last=i;}}let tail=encoder.flush();if(tail.length)parts.push(new Uint8Array(tail));let size=parts.reduce((s,a)=>s+a.length,0),out=new Uint8Array(size),offset=0;for(let p of parts){out.set(p,offset);offset+=p.length;}self.postMessage({mp3:out.buffer},[out.buffer]);}catch(e){self.postMessage({error:e.message});}};
